window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e4d64c93cc2eb85e"]={"versions": [{"id": "FIG-e4d64c93cc2eb85e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitablaufdiagramm (Execution & Timing Diagram) zur Veranschaulichung des Aufrufverhaltens einer Überwachungsfunktion (Monitor Function).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Ausführungs- und Meldezeitpunkts von Diagnoseereignissen an den Diagnostic Event Manager (<code>Dem</code>) via <code>Dem_SetEventStatus</code> unter Berücksichtigung von kontinuierlichen vs. unterbrochenen Überwachungszyklen (z. B. durch Inhibition via <code>FiM</code> oder Enable Conditions).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen der Diagnose-Applikationsebene (SW-C-Monitore) bzw. BSW-Modultreibern und dem AUTOSAR Classic BSW Diagnostic Event Manager (<code>Dem</code>), optional gekoppelt mit dem Function Inhibition Manager (<code>FiM</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Module:</strong></li>\n<li><strong>Monitor Function:</strong> Diagnose-Überwachungsroutine innerhalb einer SW-C oder eines BSW-Treibers (Sensor-, Aktuator-, Stack-Monitor).</li>\n<li><strong>Dem (Diagnostic Event Manager):</strong> BSW-Dienst zur Verarbeitung, Entprellung (Debouncing) und Speicherung des Event- und UDS-DTC-Status.</li>\n<li><strong>FiM (Function Inhibition Manager) & Enable Conditions:</strong> Steuerungsinstanzen, die Monitorfunktionen bei unzureichenden Randbedingungen (z. B. Unterspannung, Drehzahl-/Temperaturbereich außerhalb Spezifikation) hemmen oder deaktivieren.</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>C-API (BSW):</strong> <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code></li>\n<li><strong>RTE-Port (SW-C):</strong> Port-Interface <code>DiagnosticMonitor</code> (Client-Server), Operation <code>SetEventStatus(Dem_EventStatusType EventStatus)</code>.</li>\n<li><strong>Parameter-Typen:</strong></li>\n<li><code>EventId</code>: 1-basierter Identifier des Diagnoseereignisses (<code>Dem_EventIdType</code>, <code>uint16</code>).</li>\n<li><code>EventStatus</code>: Statusqualifikator (<code>DEM_EVENT_STATUS_PASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, optional <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_PREFAILED</code> bei Dem-interner Entprellung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei Ausführungsszenarien entlang der Zeitachse $t$ gegenüber:</p>\n<ol class=\"fig-list\">\n<li><strong>Kontinuierlicher Zyklus (Continuous Monitoring, links):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Phase 1 (Monitor function running):</strong> Monitor sammelt kontinuierlich Messdaten / Fehlersymptome über einen definierten Erfassungszeitraum.</li>\n<li><strong>Phase 2 (Event Status evaluation):</strong> Abschluss der Fehlerbewertung am Zyklusende.</li>\n<li><strong>Phase 3 (Dem_SetEventStatus Trigger):</strong> Synchroner Aufruf von <code>Dem_SetEventStatus</code> zur Übergabe des qualifizierten Ergebnisses (<code>PASSED</code> oder <code>FAILED</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterbrochener / Fragmentierter Zyklus (Interrupted Monitoring, rechts):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Initialer Lauf:</strong> Monitor beginnt Fehlerabtastung.</li>\n<li><strong>Unterbrechung (Monitor function stopped):</strong> Monitor pausiert (gekennzeichnet durch Schraffur), wenn Freigabebedingungen nicht erfüllt sind (z. B. <code>FiM</code>-Inhibition aktiv, Kühlmitteltemperatur außerhalb Schwellwert, Bordnetzspannung instabil, Fahrzeuggeschwindigkeit $v > v_{max}$).</li>\n<li><strong>Akkumulation / Fortsetzung:</strong> Nach Wiederherstellung der Freigabe setzt der Monitor die Auswertung fort. Zwischenergebnisse dürfen nicht verworfen werden, sofern kein Reset-Kriterium greift.</li>\n<li><strong>Abschluss (Event Status evaluation):</strong> Erst nach Erreichen der vollständigen, kumulierten Testdauer/Prüftiefe erfolgt die finale Statusentscheidung.</li>\n<li><strong>Trigger:</strong> Einmaliger Aufruf von <code>Dem_SetEventStatus(passed | failed)</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (<code>SWS_Dem_00051</code>, <code>SWS_Dem_00107</code>):</strong></li>\n<li><code>Dem_SetEventStatus</code> darf <strong>nur dann</strong> aufgerufen werden, wenn eine eindeutige Bewertung (<code>Evaluation</code>) abgeschlossen ist. Zyklisches Melden von Zwischenständen ohne Statusänderung oder vor Erreichen der Diagnosequalifikation belastet unnötig die Dem-Warteschlange und den NVRAM-Pfad.</li>\n<li><strong>Handling von Enable Conditions & FiM (<code>SWS_Dem_00331</code>):</strong></li>\n<li>Solange die Monitorfunktion gestoppt/gehemmt ist, darf <strong>kein</strong> <code>Dem_SetEventStatus</code> abgesetzt werden (weder <code>PASSED</code> noch <code>FAILED</code>).</li>\n<li>Vor Aufruf von Diagnosezyklen ist im Monitor <code>FiM_GetFunctionPermission</code> abzufragen oder die konfigurierte <code>DemEnableCondition</code> zu beachten.</li>\n<li><strong>Entprellung (Debouncing) (<code>SWS_Dem_00187</code>, <code>SWS_Dem_00638</code>):</strong></li>\n<li><em>Monitor-interne Entprellung:</em> Monitor akkumuliert die Fehlerzustände selbstständig und übergibt final ausschließlich <code>DEM_EVENT_STATUS_PASSED</code> oder <code>DEM_EVENT_STATUS_FAILED</code>.</li>\n<li><em>Dem-basierte Entprellung (Counter/Time-based):</em> Bei Verwendung von <code>PREPASSED</code> / <code>PREFAILED</code> muss der Monitor sicherstellen, dass Inaktivitätsphasen die Dem-Timer nicht fälschlich weitertakten (z. B. Dem-intern über Freeze/Enable Conditions abfangen).</li>\n<li><strong>Reentrancy & Task-Kontext:</strong></li>\n<li><code>Dem_SetEventStatus</code> ist reentrant für unterschiedliche <code>EventId</code>s, jedoch <strong>non-reentrant für dieselbe <code>EventId</code></strong>. Parallele Aufrufe aus unterbrechenden ISRs oder höherprioren Tasks für dieselbe <code>EventId</code> sind unzulässig.</li>\n</ul>"}, {"id": "FIG-a8749c26aa3db70b", "releases": ["R4.2.2", "R19-11", "R20-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitablaufdiagramm (Execution & Timing Diagram) zur Veranschaulichung des Aufrufverhaltens einer Überwachungsfunktion (Monitor Function).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Ausführungs- und Meldezeitpunkts von Diagnoseereignissen an den Diagnostic Event Manager (<code>Dem</code>) via <code>Dem_SetEventStatus</code> unter Berücksichtigung von kontinuierlichen vs. unterbrochenen Überwachungszyklen (z. B. durch Inhibition via <code>FiM</code> oder Enable Conditions).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen der Diagnose-Applikationsebene (SW-C-Monitore) bzw. BSW-Modultreibern und dem AUTOSAR Classic BSW Diagnostic Event Manager (<code>Dem</code>), optional gekoppelt mit dem Function Inhibition Manager (<code>FiM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Module:</strong></li>\n<li><strong>Monitor Function:</strong> Diagnose-Überwachungsroutine innerhalb einer SW-C oder eines BSW-Treibers (Sensor-, Aktuator-, Stack-Monitor).</li>\n<li><strong>Dem (Diagnostic Event Manager):</strong> BSW-Dienst zur Verarbeitung, Entprellung (Debouncing) und Speicherung des Event- und UDS-DTC-Status.</li>\n<li><strong>FiM (Function Inhibition Manager) & Enable Conditions:</strong> Steuerungsinstanzen, die Monitorfunktionen bei unzureichenden Randbedingungen (z. B. Unterspannung, Drehzahl-/Temperaturbereich außerhalb Spezifikation) hemmen oder deaktivieren.</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>C-API (BSW):</strong> <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code></li>\n<li><strong>RTE-Port (SW-C):</strong> Port-Interface <code>DiagnosticMonitor</code> (Client-Server), Operation <code>SetEventStatus(Dem_EventStatusType EventStatus)</code>.</li>\n<li><strong>Parameter-Typen:</strong></li>\n<li><code>EventId</code>: 1-basierter Identifier des Diagnoseereignisses (<code>Dem_EventIdType</code>, <code>uint16</code>).</li>\n<li><code>EventStatus</code>: Statusqualifikator (<code>DEM_EVENT_STATUS_PASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, optional <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_PREFAILED</code> bei Dem-interner Entprellung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei Ausführungsszenarien entlang der Zeitachse $t$ gegenüber:</p>\n<ol class=\"fig-list\">\n<li><strong>Kontinuierlicher Zyklus (Continuous Monitoring, links):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Phase 1 (Monitor function running):</strong> Monitor sammelt kontinuierlich Messdaten / Fehlersymptome über einen definierten Erfassungszeitraum.</li>\n<li><strong>Phase 2 (Event Status evaluation):</strong> Abschluss der Fehlerbewertung am Zyklusende.</li>\n<li><strong>Phase 3 (Dem_SetEventStatus Trigger):</strong> Synchroner Aufruf von <code>Dem_SetEventStatus</code> zur Übergabe des qualifizierten Ergebnisses (<code>PASSED</code> oder <code>FAILED</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterbrochener / Fragmentierter Zyklus (Interrupted Monitoring, rechts):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Initialer Lauf:</strong> Monitor beginnt Fehlerabtastung.</li>\n<li><strong>Unterbrechung (Monitor function stopped):</strong> Monitor pausiert (gekennzeichnet durch Schraffur), wenn Freigabebedingungen nicht erfüllt sind (z. B. <code>FiM</code>-Inhibition aktiv, Kühlmitteltemperatur außerhalb Schwellwert, Bordnetzspannung instabil, Fahrzeuggeschwindigkeit $v > v_{max}$).</li>\n<li><strong>Akkumulation / Fortsetzung:</strong> Nach Wiederherstellung der Freigabe setzt der Monitor die Auswertung fort. Zwischenergebnisse dürfen nicht verworfen werden, sofern kein Reset-Kriterium greift.</li>\n<li><strong>Abschluss (Event Status evaluation):</strong> Erst nach Erreichen der vollständigen, kumulierten Testdauer/Prüftiefe erfolgt die finale Statusentscheidung.</li>\n<li><strong>Trigger:</strong> Einmaliger Aufruf von <code>Dem_SetEventStatus(passed | failed)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (<code>SWS_Dem_00051</code>, <code>SWS_Dem_00107</code>):</strong></li>\n<li><code>Dem_SetEventStatus</code> darf <strong>nur dann</strong> aufgerufen werden, wenn eine eindeutige Bewertung (<code>Evaluation</code>) abgeschlossen ist. Zyklisches Melden von Zwischenständen ohne Statusänderung oder vor Erreichen der Diagnosequalifikation belastet unnötig die Dem-Warteschlange und den NVRAM-Pfad.</li>\n<li><strong>Handling von Enable Conditions & FiM (<code>SWS_Dem_00331</code>):</strong></li>\n<li>Solange die Monitorfunktion gestoppt/gehemmt ist, darf <strong>kein</strong> <code>Dem_SetEventStatus</code> abgesetzt werden (weder <code>PASSED</code> noch <code>FAILED</code>).</li>\n<li>Vor Aufruf von Diagnosezyklen ist im Monitor <code>FiM_GetFunctionPermission</code> abzufragen oder die konfigurierte <code>DemEnableCondition</code> zu beachten.</li>\n<li><strong>Entprellung (Debouncing) (<code>SWS_Dem_00187</code>, <code>SWS_Dem_00638</code>):</strong></li>\n<li><em>Monitor-interne Entprellung:</em> Monitor akkumuliert die Fehlerzustände selbstständig und übergibt final ausschließlich <code>DEM_EVENT_STATUS_PASSED</code> oder <code>DEM_EVENT_STATUS_FAILED</code>.</li>\n<li><em>Dem-basierte Entprellung (Counter/Time-based):</em> Bei Verwendung von <code>PREPASSED</code> / <code>PREFAILED</code> muss der Monitor sicherstellen, dass Inaktivitätsphasen die Dem-Timer nicht fälschlich weitertakten (z. B. Dem-intern über Freeze/Enable Conditions abfangen).</li>\n<li><strong>Reentrancy & Task-Kontext:</strong></li>\n<li><code>Dem_SetEventStatus</code> ist reentrant für unterschiedliche <code>EventId</code>s, jedoch <strong>non-reentrant für dieselbe <code>EventId</code></strong>. Parallele Aufrufe aus unterbrechenden ISRs oder höherprioren Tasks für dieselbe <code>EventId</code> sind unzulässig.</li>\n</ul>"}, {"id": "FIG-6b7cf0ba646a9cdd", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitablaufdiagramm (Execution & Timing Diagram) zur Veranschaulichung des Aufrufverhaltens einer Überwachungsfunktion (Monitor Function).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Ausführungs- und Meldezeitpunkts von Diagnoseereignissen an den Diagnostic Event Manager (<code>Dem</code>) via <code>Dem_SetEventStatus</code> unter Berücksichtigung von kontinuierlichen vs. unterbrochenen Überwachungszyklen (z. B. durch Inhibition via <code>FiM</code> oder Enable Conditions).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen der Diagnose-Applikationsebene (SW-C-Monitore) bzw. BSW-Modultreibern und dem AUTOSAR Classic BSW Diagnostic Event Manager (<code>Dem</code>), optional gekoppelt mit dem Function Inhibition Manager (<code>FiM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Module:</strong></li>\n<li><strong>Monitor Function:</strong> Diagnose-Überwachungsroutine innerhalb einer SW-C oder eines BSW-Treibers (Sensor-, Aktuator-, Stack-Monitor).</li>\n<li><strong>Dem (Diagnostic Event Manager):</strong> BSW-Dienst zur Verarbeitung, Entprellung (Debouncing) und Speicherung des Event- und UDS-DTC-Status.</li>\n<li><strong>FiM (Function Inhibition Manager) & Enable Conditions:</strong> Steuerungsinstanzen, die Monitorfunktionen bei unzureichenden Randbedingungen (z. B. Unterspannung, Drehzahl-/Temperaturbereich außerhalb Spezifikation) hemmen oder deaktivieren.</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>C-API (BSW):</strong> <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code></li>\n<li><strong>RTE-Port (SW-C):</strong> Port-Interface <code>DiagnosticMonitor</code> (Client-Server), Operation <code>SetEventStatus(Dem_EventStatusType EventStatus)</code>.</li>\n<li><strong>Parameter-Typen:</strong></li>\n<li><code>EventId</code>: 1-basierter Identifier des Diagnoseereignisses (<code>Dem_EventIdType</code>, <code>uint16</code>).</li>\n<li><code>EventStatus</code>: Statusqualifikator (<code>DEM_EVENT_STATUS_PASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, optional <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_PREFAILED</code> bei Dem-interner Entprellung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei Ausführungsszenarien entlang der Zeitachse $t$ gegenüber:</p>\n<ol class=\"fig-list\">\n<li><strong>Kontinuierlicher Zyklus (Continuous Monitoring, links):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Phase 1 (Monitor function running):</strong> Monitor sammelt kontinuierlich Messdaten / Fehlersymptome über einen definierten Erfassungszeitraum.</li>\n<li><strong>Phase 2 (Event Status evaluation):</strong> Abschluss der Fehlerbewertung am Zyklusende.</li>\n<li><strong>Phase 3 (Dem_SetEventStatus Trigger):</strong> Synchroner Aufruf von <code>Dem_SetEventStatus</code> zur Übergabe des qualifizierten Ergebnisses (<code>PASSED</code> oder <code>FAILED</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterbrochener / Fragmentierter Zyklus (Interrupted Monitoring, rechts):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Initialer Lauf:</strong> Monitor beginnt Fehlerabtastung.</li>\n<li><strong>Unterbrechung (Monitor function stopped):</strong> Monitor pausiert (gekennzeichnet durch Schraffur), wenn Freigabebedingungen nicht erfüllt sind (z. B. <code>FiM</code>-Inhibition aktiv, Kühlmitteltemperatur außerhalb Schwellwert, Bordnetzspannung instabil, Fahrzeuggeschwindigkeit $v > v_{max}$).</li>\n<li><strong>Akkumulation / Fortsetzung:</strong> Nach Wiederherstellung der Freigabe setzt der Monitor die Auswertung fort. Zwischenergebnisse dürfen nicht verworfen werden, sofern kein Reset-Kriterium greift.</li>\n<li><strong>Abschluss (Event Status evaluation):</strong> Erst nach Erreichen der vollständigen, kumulierten Testdauer/Prüftiefe erfolgt die finale Statusentscheidung.</li>\n<li><strong>Trigger:</strong> Einmaliger Aufruf von <code>Dem_SetEventStatus(passed | failed)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (<code>SWS_Dem_00051</code>, <code>SWS_Dem_00107</code>):</strong></li>\n<li><code>Dem_SetEventStatus</code> darf <strong>nur dann</strong> aufgerufen werden, wenn eine eindeutige Bewertung (<code>Evaluation</code>) abgeschlossen ist. Zyklisches Melden von Zwischenständen ohne Statusänderung oder vor Erreichen der Diagnosequalifikation belastet unnötig die Dem-Warteschlange und den NVRAM-Pfad.</li>\n<li><strong>Handling von Enable Conditions & FiM (<code>SWS_Dem_00331</code>):</strong></li>\n<li>Solange die Monitorfunktion gestoppt/gehemmt ist, darf <strong>kein</strong> <code>Dem_SetEventStatus</code> abgesetzt werden (weder <code>PASSED</code> noch <code>FAILED</code>).</li>\n<li>Vor Aufruf von Diagnosezyklen ist im Monitor <code>FiM_GetFunctionPermission</code> abzufragen oder die konfigurierte <code>DemEnableCondition</code> zu beachten.</li>\n<li><strong>Entprellung (Debouncing) (<code>SWS_Dem_00187</code>, <code>SWS_Dem_00638</code>):</strong></li>\n<li><em>Monitor-interne Entprellung:</em> Monitor akkumuliert die Fehlerzustände selbstständig und übergibt final ausschließlich <code>DEM_EVENT_STATUS_PASSED</code> oder <code>DEM_EVENT_STATUS_FAILED</code>.</li>\n<li><em>Dem-basierte Entprellung (Counter/Time-based):</em> Bei Verwendung von <code>PREPASSED</code> / <code>PREFAILED</code> muss der Monitor sicherstellen, dass Inaktivitätsphasen die Dem-Timer nicht fälschlich weitertakten (z. B. Dem-intern über Freeze/Enable Conditions abfangen).</li>\n<li><strong>Reentrancy & Task-Kontext:</strong></li>\n<li><code>Dem_SetEventStatus</code> ist reentrant für unterschiedliche <code>EventId</code>s, jedoch <strong>non-reentrant für dieselbe <code>EventId</code></strong>. Parallele Aufrufe aus unterbrechenden ISRs oder höherprioren Tasks für dieselbe <code>EventId</code> sind unzulässig.</li>\n</ul>"}, {"id": "FIG-10ebdaa247dbe624", "releases": ["R18-10_R4.4.0_R1.5.0", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Zeitablaufdiagramm (Execution & Timing Diagram) zur Veranschaulichung des Aufrufverhaltens einer Überwachungsfunktion (Monitor Function).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Ausführungs- und Meldezeitpunkts von Diagnoseereignissen an den Diagnostic Event Manager (<code>Dem</code>) via <code>Dem_SetEventStatus</code> unter Berücksichtigung von kontinuierlichen vs. unterbrochenen Überwachungszyklen (z. B. durch Inhibition via <code>FiM</code> oder Enable Conditions).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen der Diagnose-Applikationsebene (SW-C-Monitore) bzw. BSW-Modultreibern und dem AUTOSAR Classic BSW Diagnostic Event Manager (<code>Dem</code>), optional gekoppelt mit dem Function Inhibition Manager (<code>FiM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Module:</strong></li>\n<li><strong>Monitor Function:</strong> Diagnose-Überwachungsroutine innerhalb einer SW-C oder eines BSW-Treibers (Sensor-, Aktuator-, Stack-Monitor).</li>\n<li><strong>Dem (Diagnostic Event Manager):</strong> BSW-Dienst zur Verarbeitung, Entprellung (Debouncing) und Speicherung des Event- und UDS-DTC-Status.</li>\n<li><strong>FiM (Function Inhibition Manager) & Enable Conditions:</strong> Steuerungsinstanzen, die Monitorfunktionen bei unzureichenden Randbedingungen (z. B. Unterspannung, Drehzahl-/Temperaturbereich außerhalb Spezifikation) hemmen oder deaktivieren.</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>C-API (BSW):</strong> <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code></li>\n<li><strong>RTE-Port (SW-C):</strong> Port-Interface <code>DiagnosticMonitor</code> (Client-Server), Operation <code>SetEventStatus(Dem_EventStatusType EventStatus)</code>.</li>\n<li><strong>Parameter-Typen:</strong></li>\n<li><code>EventId</code>: 1-basierter Identifier des Diagnoseereignisses (<code>Dem_EventIdType</code>, <code>uint16</code>).</li>\n<li><code>EventStatus</code>: Statusqualifikator (<code>DEM_EVENT_STATUS_PASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, optional <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_PREFAILED</code> bei Dem-interner Entprellung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei Ausführungsszenarien entlang der Zeitachse $t$ gegenüber:</p>\n<ol class=\"fig-list\">\n<li><strong>Kontinuierlicher Zyklus (Continuous Monitoring, links):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Phase 1 (Monitor function running):</strong> Monitor sammelt kontinuierlich Messdaten / Fehlersymptome über einen definierten Erfassungszeitraum.</li>\n<li><strong>Phase 2 (Event Status evaluation):</strong> Abschluss der Fehlerbewertung am Zyklusende.</li>\n<li><strong>Phase 3 (Dem_SetEventStatus Trigger):</strong> Synchroner Aufruf von <code>Dem_SetEventStatus</code> zur Übergabe des qualifizierten Ergebnisses (<code>PASSED</code> oder <code>FAILED</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterbrochener / Fragmentierter Zyklus (Interrupted Monitoring, rechts):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Initialer Lauf:</strong> Monitor beginnt Fehlerabtastung.</li>\n<li><strong>Unterbrechung (Monitor function stopped):</strong> Monitor pausiert (gekennzeichnet durch Schraffur), wenn Freigabebedingungen nicht erfüllt sind (z. B. <code>FiM</code>-Inhibition aktiv, Kühlmitteltemperatur außerhalb Schwellwert, Bordnetzspannung instabil, Fahrzeuggeschwindigkeit $v > v_{max}$).</li>\n<li><strong>Akkumulation / Fortsetzung:</strong> Nach Wiederherstellung der Freigabe setzt der Monitor die Auswertung fort. Zwischenergebnisse dürfen nicht verworfen werden, sofern kein Reset-Kriterium greift.</li>\n<li><strong>Abschluss (Event Status evaluation):</strong> Erst nach Erreichen der vollständigen, kumulierten Testdauer/Prüftiefe erfolgt die finale Statusentscheidung.</li>\n<li><strong>Trigger:</strong> Einmaliger Aufruf von <code>Dem_SetEventStatus(passed | failed)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (<code>SWS_Dem_00051</code>, <code>SWS_Dem_00107</code>):</strong></li>\n<li><code>Dem_SetEventStatus</code> darf <strong>nur dann</strong> aufgerufen werden, wenn eine eindeutige Bewertung (<code>Evaluation</code>) abgeschlossen ist. Zyklisches Melden von Zwischenständen ohne Statusänderung oder vor Erreichen der Diagnosequalifikation belastet unnötig die Dem-Warteschlange und den NVRAM-Pfad.</li>\n<li><strong>Handling von Enable Conditions & FiM (<code>SWS_Dem_00331</code>):</strong></li>\n<li>Solange die Monitorfunktion gestoppt/gehemmt ist, darf <strong>kein</strong> <code>Dem_SetEventStatus</code> abgesetzt werden (weder <code>PASSED</code> noch <code>FAILED</code>).</li>\n<li>Vor Aufruf von Diagnosezyklen ist im Monitor <code>FiM_GetFunctionPermission</code> abzufragen oder die konfigurierte <code>DemEnableCondition</code> zu beachten.</li>\n<li><strong>Entprellung (Debouncing) (<code>SWS_Dem_00187</code>, <code>SWS_Dem_00638</code>):</strong></li>\n<li><em>Monitor-interne Entprellung:</em> Monitor akkumuliert die Fehlerzustände selbstständig und übergibt final ausschließlich <code>DEM_EVENT_STATUS_PASSED</code> oder <code>DEM_EVENT_STATUS_FAILED</code>.</li>\n<li><em>Dem-basierte Entprellung (Counter/Time-based):</em> Bei Verwendung von <code>PREPASSED</code> / <code>PREFAILED</code> muss der Monitor sicherstellen, dass Inaktivitätsphasen die Dem-Timer nicht fälschlich weitertakten (z. B. Dem-intern über Freeze/Enable Conditions abfangen).</li>\n<li><strong>Reentrancy & Task-Kontext:</strong></li>\n<li><code>Dem_SetEventStatus</code> ist reentrant für unterschiedliche <code>EventId</code>s, jedoch <strong>non-reentrant für dieselbe <code>EventId</code></strong>. Parallele Aufrufe aus unterbrechenden ISRs oder höherprioren Tasks für dieselbe <code>EventId</code> sind unzulässig.</li>\n</ul>"}], "trans": [{"from": "FIG-e4d64c93cc2eb85e", "to": "FIG-a8749c26aa3db70b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a8749c26aa3db70b", "to": "FIG-6b7cf0ba646a9cdd", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6b7cf0ba646a9cdd", "to": "FIG-10ebdaa247dbe624", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-10ebdaa247dbe624", "to": "FIG-a8749c26aa3db70b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a8749c26aa3db70b", "to": "FIG-10ebdaa247dbe624", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
